contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public {
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        // If we reach here, SetLogFile did not revert, so the address was accepted.
        assert(true);
    }

    receive() external payable {}
}

